{"codeContent":"import ast
import math


# ---------- Anti-pattern: naive evaluator ----------
def calculate(expr: str):
    """DANGEROUS: full Python semantics on untrusted input."""
    return eval(expr, {"__builtins__": __builtins__, "math": math})  # noqa: S307


# ---------- Slightly better, still unsafe ----------
def calculate_ast(expr: str):
    tree = ast.parse(expr, mode="eval")  # no depth/length limit
    # No node whitelist: Attribute, Call, Subscript, Lambda all reachable
    return eval(compile(tree, "<expr>", "eval"))  # noqa: S307


# ---------- Unbounded exponent ----------
def power(a, b):
    return a ** b  # 9 ** 9 ** 9 -> CPU/memory DoS, no magnitude guard


# ---------- Money math with floats ----------
def price_total(items):
    total = 0.0
    for price, qty in items:
        total += price * qty  # float rounding drift, no Decimal, no quantize
    return total


# ---------- Error handling leaks internals ----------
def parse_rule(rule: str) -> dict:
    try:
        return {"rule": rule, "value": calculate(rule)}
    except Exception as e:
        return {"error": f"{type(e).__name__}: {e}", "trace": repr(e)}  # info leak
